 100→func TestWorktreeRoot_Cache(t *testing.T) {
 101→	// Uses t.Chdir + t.Setenv so cannot be parallel.
 102→	tmpDir := t.TempDir()
 103→	initTestRepo(t, tmpDir)
 104→	t.Chdir(tmpDir)
 105→	paths.ClearWorktreeRootCache()
 106→
 107→	// First call populates the cache via git.
 108→	got, err := paths.WorktreeRoot()
 109→	if err != nil {
 110→		t.Fatalf("paths.WorktreeRoot() first call error: %v", err)
 111→	}
 112→
 113→	// Resolve symlinks for comparison (macOS /var -> /private/var).
 114→	want, err := filepath.EvalSymlinks(tmpDir)
 115→	if err != nil {
 116→		t.Fatalf("EvalSymlinks error: %v", err)
 117→	}
 118→	if got != want {
 119→		t.Fatalf("paths.WorktreeRoot() = %q, want %q", got, want)
 120→	}
 121→
 122→	// Break git by pointing PATH at an empty directory.
 123→	// If the second call hits git it will fail.
 124→	emptyDir := t.TempDir()
 125→	t.Setenv("PATH", emptyDir)
 126→
 127→	got2, err := paths.WorktreeRoot()
 128→	if err != nil {
 129→		t.Fatalf("paths.WorktreeRoot() cached call should succeed, got error: %v", err)
 130→	}
 131→	if got2 != want {
 132→		t.Fatalf("paths.WorktreeRoot() cached = %q, want %q", got2, want)
 133→	}
 134→
 135→	// After clearing the cache the broken PATH should cause a failure.
 136→	paths.ClearWorktreeRootCache()
 137→	_, err = paths.WorktreeRoot()
 138→	if err == nil {
 139→		t.Fatal("paths.WorktreeRoot() should fail after cache clear with broken PATH")
 140→	}
 141→}
