 182→func TestWorktreeRoot_Worktree(t *testing.T) {
 183→	// In a git worktree, WorktreeRoot must return the worktree's own root,
 184→	// NOT the main repository root. The worktree is placed in a separate
 185→	// temp directory (sibling, not child) so the two paths share no prefix.
 186→	// Uses t.Chdir so cannot be parallel.
 187→	mainDir := t.TempDir()
 188→	mainResolved, err := filepath.EvalSymlinks(mainDir)
 189→	if err != nil {
 190→		t.Fatalf("EvalSymlinks error: %v", err)
 191→	}
 192→	mainDir = mainResolved
 193→
 194→	initTestRepo(t, mainDir)
 195→
 196→	worktreeDir := t.TempDir()
 197→	wtResolved, err := filepath.EvalSymlinks(worktreeDir)
 198→	if err != nil {
 199→		t.Fatalf("EvalSymlinks error: %v", err)
 200→	}
 201→	worktreeDir = wtResolved
 202→
 203→	// t.TempDir() creates the directory; git worktree add needs it to not exist.
 204→	if err := os.Remove(worktreeDir); err != nil {
 205→		t.Fatalf("failed to remove temp dir for worktree: %v", err)
 206→	}
 207→	if err := createWorktree(mainDir, worktreeDir, "wt-branch"); err != nil {
 208→		t.Fatalf("failed to create worktree: %v", err)
 209→	}
 210→	t.Cleanup(func() { removeWorktree(mainDir, worktreeDir) })
 211→
 212→	t.Chdir(worktreeDir)
 213→	paths.ClearWorktreeRootCache()
 214→
 215→	got, err := paths.WorktreeRoot()
 216→	if err != nil {
 217→		t.Fatalf("paths.WorktreeRoot() error: %v", err)
 218→	}
 219→	if got != worktreeDir {
 220→		t.Errorf("paths.WorktreeRoot() = %q, want worktree root %q", got, worktreeDir)
 221→	}
 222→	if got == mainDir {
 223→		t.Errorf("paths.WorktreeRoot() returned main repo root %q, must return worktree root", mainDir)
 224→	}
 225→
 226→	// Also works from a subdirectory within the worktree.
 227→	subDir := filepath.Join(worktreeDir, "deep", "sub")
 228→	if err := os.MkdirAll(subDir, 0o755); err != nil {
 229→		t.Fatalf("failed to create subdir: %v", err)
 230→	}
 231→	t.Chdir(subDir)
 232→	paths.ClearWorktreeRootCache()
 233→
 234→	got, err = paths.WorktreeRoot()
 235→	if err != nil {
 236→		t.Fatalf("paths.WorktreeRoot() from worktree subdir error: %v", err)
 237→	}
 238→	if got != worktreeDir {
 239→		t.Errorf("paths.WorktreeRoot() from worktree subdir = %q, want %q", got, worktreeDir)
 240→	}
 241→	if got == mainDir {
 242→		t.Errorf("paths.WorktreeRoot() from worktree subdir returned main repo root %q", mainDir)
 243→	}
 244→}
