// TestEnsureMetadataBranch_FromRemote tests that EnsureMetadataBranch creates
// the local branch from the remote-tracking branch when available (e.g., after clone).
func TestEnsureMetadataBranch_FromRemote(t *testing.T) {
	// Step 1: Create a "remote" bare repo with entire/checkpoints/v1 branch
	bareDir := t.TempDir()
	bareRepo, err := git.PlainInit(bareDir, true)
	if err != nil {
		t.Fatalf("failed to init bare repo: %v", err)
	}

	// Create a commit with some checkpoint data on entire/checkpoints/v1
	checkpointContent := []byte(`{"checkpoint_id": "test123"}`)
	blob := bareRepo.Storer.NewEncodedObject()
	blob.SetType(plumbing.BlobObject)
	blob.SetSize(int64(len(checkpointContent)))
	w, err := blob.Writer()
	if err != nil {
		t.Fatalf("failed to get blob writer: %v", err)
	}
	if _, err := w.Write(checkpointContent); err != nil {
		t.Fatalf("failed to write blob: %v", err)
	}
	if err := w.Close(); err != nil {
		t.Fatalf("failed to close blob writer: %v", err)
	}
	blobHash, err := bareRepo.Storer.SetEncodedObject(blob)
	if err != nil {
		t.Fatalf("failed to store blob: %v", err)
	}

	// Build a tree with the blob
	tree := &object.Tree{
		Entries: []object.TreeEntry{
			{Name: "metadata.json", Mode: 0o100644, Hash: blobHash},
		},
	}
	treeObj := bareRepo.Storer.NewEncodedObject()
	if err := tree.Encode(treeObj); err != nil {
		t.Fatalf("failed to encode tree: %v", err)
	}
	treeHash, err := bareRepo.Storer.SetEncodedObject(treeObj)
	if err != nil {
		t.Fatalf("failed to store tree: %v", err)
	}

	// Create an orphan commit on entire/checkpoints/v1
	sig := object.Signature{Name: "Test", Email: "test@test.com"}
	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   "Checkpoint: test123\n",
	}
	commitObj := bareRepo.Storer.NewEncodedObject()
	if err := commit.Encode(commitObj); err != nil {
		t.Fatalf("failed to encode commit: %v", err)
	}
	commitHash, err := bareRepo.Storer.SetEncodedObject(commitObj)
	if err != nil {
		t.Fatalf("failed to store commit: %v", err)
	}

	// Set the branch ref
	metadataRef := plumbing.NewHashReference(
		plumbing.NewBranchReferenceName(paths.MetadataBranchName),
		commitHash,
	)
	if err := bareRepo.Storer.SetReference(metadataRef); err != nil {
		t.Fatalf("failed to set metadata branch ref: %v", err)
	}

	// Also create a main branch with a dummy commit for clone to work
	mainBlob := bareRepo.Storer.NewEncodedObject()
	mainBlob.SetType(plumbing.BlobObject)
	mainBlob.SetSize(4)
	mw, _ := mainBlob.Writer()
	mw.Write([]byte("test"))
	mw.Close()
	mainBlobHash, _ := bareRepo.Storer.SetEncodedObject(mainBlob)

	mainTree := &object.Tree{
		Entries: []object.TreeEntry{
			{Name: "README.md", Mode: 0o100644, Hash: mainBlobHash},
		},
	}
	mainTreeObj := bareRepo.Storer.NewEncodedObject()
	mainTree.Encode(mainTreeObj)
	mainTreeHash, _ := bareRepo.Storer.SetEncodedObject(mainTreeObj)

	mainCommit := &object.Commit{
		TreeHash:  mainTreeHash,
		Author:    sig,
		Committer: sig,
		Message:   "Initial commit\n",
	}
	mainCommitObj := bareRepo.Storer.NewEncodedObject()
	mainCommit.Encode(mainCommitObj)
	mainCommitHash, _ := bareRepo.Storer.SetEncodedObject(mainCommitObj)

	mainRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("main"), mainCommitHash)
	bareRepo.Storer.SetReference(mainRef)
	// Set HEAD to main
	headRef := plumbing.NewSymbolicReference(plumbing.HEAD, plumbing.NewBranchReferenceName("main"))
	bareRepo.Storer.SetReference(headRef)

	// Step 2: Clone the bare repo using native git (most realistic)
	cloneDir := filepath.Join(t.TempDir(), "clone")
	cmd := exec.Command("git", "clone", bareDir, cloneDir)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("failed to clone: %v\noutput: %s", err, out)
	}

	// Debug: List all refs in the clone
	t.Log("=== Refs after clone (git branch -a) ===")
	cmd = exec.Command("git", "branch", "-a")
	cmd.Dir = cloneDir
	out, _ = cmd.CombinedOutput()
	t.Logf("%s", out)

	t.Log("=== All refs (git for-each-ref) ===")
	cmd = exec.Command("git", "for-each-ref")
	cmd.Dir = cloneDir
	out, _ = cmd.CombinedOutput()
	t.Logf("%s", out)

	// Step 3: Open with go-git and inspect refs
	cloneRepo, err := git.PlainOpenWithOptions(cloneDir, &git.PlainOpenOptions{
		EnableDotGitCommonDir: true,
	})
	if err != nil {
		t.Fatalf("failed to open cloned repo: %v", err)
	}

	t.Log("=== go-git refs ===")
	refs, _ := cloneRepo.References()
	refs.ForEach(func(ref *plumbing.Reference) error {
		t.Logf("  %s -> %s (type: %s)", ref.Name(), ref.Hash(), ref.Type())
		return nil
	})

	// Check specifically what go-git sees for the remote ref
	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
	t.Logf("Looking for remote ref: %s", remoteRefName)
	remoteRef, err := cloneRepo.Reference(remoteRefName, true)
	if err != nil {
		t.Logf("Remote ref NOT found via go-git: %v", err)
	} else {
		t.Logf("Remote ref found: %s -> %s", remoteRef.Name(), remoteRef.Hash())
	}

	// Also try without resolve
	remoteRef2, err := cloneRepo.Reference(remoteRefName, false)
	if err != nil {
		t.Logf("Remote ref NOT found (no resolve): %v", err)
	} else {
		t.Logf("Remote ref found (no resolve): %s -> %s", remoteRef2.Name(), remoteRef2.Hash())
	}

	// Step 4: Call EnsureMetadataBranch
	t.Log("=== Calling EnsureMetadataBranch ===")
	if err := EnsureMetadataBranch(cloneRepo); err != nil {
		t.Fatalf("EnsureMetadataBranch() failed: %v", err)
	}

	// Step 5: Verify the local branch was created with checkpoint data
	localRefName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	localRef, err := cloneRepo.Reference(localRefName, true)
	if err != nil {
		t.Fatalf("Local metadata branch not found after EnsureMetadataBranch: %v", err)
	}

	// Get the commit and verify it has data (not an empty tree)
	localCommit, err := cloneRepo.CommitObject(localRef.Hash())
	if err != nil {
		t.Fatalf("Failed to get commit from local metadata branch: %v", err)
	}

	localTree, err := localCommit.Tree()
	if err != nil {
		t.Fatalf("Failed to get tree from local metadata branch commit: %v", err)
	}

	if len(localTree.Entries) == 0 {
		t.Error("Local metadata branch has empty tree - checkpoint data was NOT preserved from remote!")
		t.Logf("Expected tree with metadata.json, got empty tree")
		t.Logf("Local branch hash: %s", localRef.Hash())
		t.Logf("Remote commit hash was: %s", commitHash)
	} else {
		t.Logf("Local metadata branch has %d entries (expected: metadata.json)", len(localTree.Entries))
		for _, entry := range localTree.Entries {
			t.Logf("  %s (%s)", entry.Name, entry.Hash)
		}
		if localRef.Hash() != commitHash {
			t.Errorf("Local branch hash %s != remote commit hash %s", localRef.Hash(), commitHash)
		}
	}

	// Also verify via native git
	t.Log("=== Verification via native git ===")
	cmd = exec.Command("git", "log", "--oneline", "-1", fmt.Sprintf("refs/heads/%s", paths.MetadataBranchName))
	cmd.Dir = cloneDir
	out, err = cmd.CombinedOutput()
	t.Logf("git log local branch: %s (err: %v)", out, err)

	cmd = exec.Command("git", "ls-tree", fmt.Sprintf("refs/heads/%s", paths.MetadataBranchName))
	cmd.Dir = cloneDir
	out, err = cmd.CombinedOutput()
	t.Logf("git ls-tree local branch: %s (err: %v)", out, err)
}

// TestEnsureMetadataBranch_NoRemote tests that EnsureMetadataBranch creates
// an empty orphan when no remote branch exists.
func TestEnsureMetadataBranch_NoRemote(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	repo, err := git.PlainInit(dir, false)
	if err != nil {
		t.Fatalf("failed to init repo: %v", err)
	}

	// Create an initial commit so repo is not empty
	testFile := filepath.Join(dir, "test.txt")
	if err := os.WriteFile(testFile, []byte("test"), 0o644); err != nil {
		t.Fatalf("failed to write file: %v", err)
	}
	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}
	if _, err := wt.Add("test.txt"); err != nil {
		t.Fatalf("failed to add: %v", err)
	}
	if _, err := wt.Commit("Initial", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
	}); err != nil {
		t.Fatalf("failed to commit: %v", err)
	}

	if err := EnsureMetadataBranch(repo); err != nil {
		t.Fatalf("EnsureMetadataBranch() failed: %v", err)
	}

	// Verify empty orphan was created
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		t.Fatalf("metadata branch not found: %v", err)
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		t.Fatalf("failed to get commit: %v", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		t.Fatalf("failed to get tree: %v", err)
	}

	if len(tree.Entries) != 0 {
		t.Errorf("expected empty tree, got %d entries", len(tree.Entries))
	}

	// Calling again should be a no-op
	if err := EnsureMetadataBranch(repo); err != nil {
		t.Fatalf("second EnsureMetadataBranch() failed: %v", err)
	}
}

