// EnsureMetadataBranch creates or updates the local entire/checkpoints/v1 branch.
//
// Three scenarios:
//  1. Local branch doesn't exist, remote does → create local from remote
//  2. Local branch exists but is empty, remote has data → update local from remote
//  3. No local or remote branch → create empty orphan
func EnsureMetadataBranch(repo *git.Repository) error {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)

	// Check if remote-tracking branch exists (e.g., after clone/fetch)
	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
	remoteRef, remoteErr := repo.Reference(remoteRefName, true)

	// Check if local branch already exists
	localRef, err := repo.Reference(refName, true)
	if err == nil {
		// Local branch exists — check if it's an empty orphan that should be
		// updated from remote. This handles the case where enable was run before
