//  1. Local branch doesn't exist, remote does → create local from remote
//  2. Local branch exists but is empty, remote has data → update local from remote
//  3. No local or remote branch → create empty orphan
func EnsureMetadataBranch(repo *git.Repository) error {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)

	// Check if remote-tracking branch exists (e.g., after clone/fetch)
	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
	remoteRef, remoteErr := repo.Reference(remoteRefName, true)

	// Check if local branch already exists
	localRef, err := repo.Reference(refName, true)
	if err == nil {
		// Local branch exists — check if it's an empty orphan that should be
		// updated from remote. This handles the case where enable was run before
		// the remote had checkpoint data (creating an empty orphan), and now the
		// remote has been fetched with real data.
		if remoteErr == nil && localRef.Hash() != remoteRef.Hash() {
			localIsEmpty, checkErr := isEmptyMetadataBranch(repo, localRef)
			if checkErr == nil && localIsEmpty {
				ref := plumbing.NewHashReference(refName, remoteRef.Hash())
				if err := repo.Storer.SetReference(ref); err != nil {
					return fmt.Errorf("failed to update metadata branch from remote: %w", err)
				}
				fmt.Fprintf(os.Stderr, "✓ Updated local branch '%s' from origin\n", paths.MetadataBranchName)
			}
		}
		return nil
	}

	// Local branch doesn't exist — create from remote if available
	if remoteErr == nil {
		ref := plumbing.NewHashReference(refName, remoteRef.Hash())
		if err := repo.Storer.SetReference(ref); err != nil {
			return fmt.Errorf("failed to create metadata branch from remote: %w", err)
		}
		fmt.Fprintf(os.Stderr, "✓ Created local branch '%s' from origin\n", paths.MetadataBranchName)
		return nil
	}

