	localAfter, err := repo.Reference(refName, true)
	if err != nil {
		t.Fatalf("local branch not found: %v", err)
	}
	if localAfter.Hash() != remoteRef.Hash() {
		t.Errorf("local was not fast-forwarded to remote: local=%s remote=%s",
