	bareDir := initBareWithMetadataBranch(t) // remote has 1 commit
	cloneDir := filepath.Join(t.TempDir(), "clone")
	cloneCmd := exec.CommandContext(context.Background(), "git", "clone", bareDir, cloneDir)
